package com.ssolab.admin.logout;
import com.nimbusds.jose.JOSEObjectType;import com.nimbusds.jose.proc.DefaultJOSEObjectTypeVerifier;
import com.ssolab.admin.config.OidcBffProperties;import java.time.Instant;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;import org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;import org.springframework.security.oauth2.jose.jws.SignatureAlgorithm;import org.springframework.security.oauth2.jwt.*;import org.springframework.stereotype.Service;
@Service public class BackChannelLogoutService {private static final String EVENT="http://schemas.openid.net/event/backchannel-logout";private final JwtDecoder decoder;private final BffSessionRegistry sessions;private final ConcurrentHashMap<String,Instant> consumed=new ConcurrentHashMap<>();public BackChannelLogoutService(OidcBffProperties p,BffSessionRegistry s){NimbusJwtDecoder d=NimbusJwtDecoder.withJwkSetUri(p.jwkSetUri().toString()).validateType(false).jwtProcessorCustomizer(processor->processor.setJWSTypeVerifier(new DefaultJOSEObjectTypeVerifier<>(new JOSEObjectType("logout+jwt")))).jwsAlgorithm(SignatureAlgorithm.RS256).build();d.setJwtValidator(new DelegatingOAuth2TokenValidator<>(new JwtTimestampValidator(),new JwtIssuerValidator(p.issuer().toString()),jwt->jwt.getAudience().contains(p.clientId())?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new org.springframework.security.oauth2.core.OAuth2Error("invalid_token"))));decoder=d;sessions=s;}public int logout(String token){Jwt jwt=decoder.decode(token);Object events=jwt.getClaim("events");String sid=jwt.getClaimAsString("sid"),sub=jwt.getSubject();if(!"logout+jwt".equals(jwt.getHeaders().get("typ"))||!(events instanceof Map<?,?> map)||!map.containsKey(EVENT)||jwt.hasClaim("nonce")||jwt.getId()==null||jwt.getIssuedAt()==null||jwt.getExpiresAt()==null||((sid==null||sid.isBlank())&&(sub==null||sub.isBlank())))throw new JwtException("invalid logout token");consumed.entrySet().removeIf(e->e.getValue().isBefore(Instant.now()));if(consumed.putIfAbsent(jwt.getId(),jwt.getExpiresAt())!=null)throw new JwtException("logout token was already used");return sessions.invalidate(sid,sub);}}
